"""
_offlinai_7z.py — a small, dependency-free 7-Zip (.7z) reader/writer.

Pure Python on top of the stdlib ``lzma`` module (which provides LZMA and
LZMA2 — the codecs 7-Zip uses by default), plus COPY (store). No native
extensions, so it works in the iOS sandbox. Powers the shell's ``7z``
builtin (create / extract / list / test).

Supported on read: COPY (0x00), LZMA (0x030101), LZMA2 (0x21), Deflate
(0x040108, via zlib), BZip2 (0x040202, via bz2), BCJ/Delta filters, and
AES-256 (0x06f10701) decryption — including encrypted headers — with a
password (UTF-16-LE → SHA-256 key-stretch → AES-256-CBC). Writes LZMA2.
Also reads ISO 9660 images (see ISOReader). Exotic codecs (PPMd, BCJ2,
Brotli, Zstd) are reported with a clear error, not silently mishandled.
"""
from __future__ import annotations

import io
import os
import lzma
import struct
import zlib
from typing import List, Optional, Tuple

MAGIC = b"7z\xbc\xaf\x27\x1c"

# Property IDs
K_END = 0x00
K_HEADER = 0x01
K_ARCHIVE_PROPERTIES = 0x02
K_ADDITIONAL_STREAMS = 0x03
K_MAIN_STREAMS = 0x04
K_FILES_INFO = 0x05
K_PACK_INFO = 0x06
K_UNPACK_INFO = 0x07
K_SUBSTREAMS_INFO = 0x08
K_SIZE = 0x09
K_CRC = 0x0A
K_FOLDER = 0x0B
K_CODERS_UNPACK_SIZE = 0x0C
K_NUM_UNPACK_STREAM = 0x0D
K_EMPTY_STREAM = 0x0E
K_EMPTY_FILE = 0x0F
K_ANTI = 0x10
K_NAME = 0x11
K_CTIME = 0x12
K_ATIME = 0x13
K_MTIME = 0x14
K_WIN_ATTR = 0x15
K_ENCODED_HEADER = 0x17
K_DUMMY = 0x19

# Codec IDs (big-endian byte strings)
C_COPY = b"\x00"
C_DELTA = b"\x03"
C_LZMA = b"\x03\x01\x01"
C_LZMA2 = b"\x21"
C_BCJ_X86 = b"\x03\x03\x01\x03"
C_BCJ2 = b"\x03\x03\x01\x1b"
C_DEFLATE = b"\x04\x01\x08"
C_BZIP2 = b"\x04\x02\x02"
C_PPMD = b"\x03\x04\x01"
C_AES = b"\x06\xf1\x07\x01"

_BCJ_FILTERS = {
    C_BCJ_X86: lzma.FILTER_X86,
    b"\x04": lzma.FILTER_X86,
    b"\x03\x03\x02\x05": getattr(lzma, "FILTER_POWERPC", None),
    b"\x03\x03\x04\x01": getattr(lzma, "FILTER_IA64", None),
    b"\x03\x03\x05\x01": getattr(lzma, "FILTER_ARM", None),
    b"\x03\x03\x07\x01": getattr(lzma, "FILTER_ARMTHUMB", None),
    b"\x03\x03\x08\x05": getattr(lzma, "FILTER_SPARC", None),
}


class SevenZError(Exception):
    pass


# ── primitive readers ───────────────────────────────────────────────────
class _R:
    def __init__(self, data: bytes):
        self.b = data
        self.i = 0

    def byte(self) -> int:
        v = self.b[self.i]
        self.i += 1
        return v

    def bytes(self, n: int) -> bytes:
        v = self.b[self.i:self.i + n]
        self.i += n
        return v

    def u32(self) -> int:
        return struct.unpack("<I", self.bytes(4))[0]

    def u64(self) -> int:
        return struct.unpack("<Q", self.bytes(8))[0]

    def number(self) -> int:
        """7z variable-length number."""
        first = self.byte()
        mask = 0x80
        value = 0
        for i in range(8):
            if first & mask == 0:
                value |= (first & (mask - 1)) << (8 * i)
                return value
            value |= self.byte() << (8 * i)
            mask >>= 1
        return value

    def bits(self, n: int) -> List[bool]:
        out, mask, cur = [], 0, 0
        for _ in range(n):
            if mask == 0:
                cur = self.byte()
                mask = 0x80
            out.append(bool(cur & mask))
            mask >>= 1
        return out

    def bits_all_or(self, n: int) -> List[bool]:
        """A bit vector that may be preceded by an 'all defined' byte."""
        if self.byte() != 0:
            return [True] * n
        return self.bits(n)


# ── codec decode ────────────────────────────────────────────────────────
def _lzma2_dict_size(prop: int) -> int:
    if prop > 40:
        raise SevenZError("bad LZMA2 dict-size byte")
    if prop == 40:
        return 0xFFFFFFFF
    return (2 | (prop & 1)) << (prop // 2 + 11)


def _decode_coder(codec_id: bytes, props: bytes, data: bytes, out_size: int) -> bytes:
    if codec_id == C_COPY:
        return data[:out_size]
    if codec_id == C_LZMA2:
        ds = _lzma2_dict_size(props[0]) if props else 0x8000000
        filt = [{"id": lzma.FILTER_LZMA2, "dict_size": ds}]
        d = lzma.LZMADecompressor(format=lzma.FORMAT_RAW, filters=filt)
        return d.decompress(data, out_size)
    if codec_id == C_LZMA:
        if len(props) < 5:
            raise SevenZError("bad LZMA props")
        lclppb = props[0]
        lc = lclppb % 9
        rem = lclppb // 9
        lp = rem % 5
        pb = rem // 5
        ds = struct.unpack("<I", props[1:5])[0]
        filt = [{"id": lzma.FILTER_LZMA1, "dict_size": max(ds, 4096),
                 "lc": lc, "lp": lp, "pb": pb}]
        d = lzma.LZMADecompressor(format=lzma.FORMAT_RAW, filters=filt)
        return d.decompress(data, out_size)
    if codec_id == C_DEFLATE:
        return zlib.decompress(data, -15)[:out_size]      # raw deflate
    if codec_id == C_BZIP2:
        import bz2
        return bz2.decompress(data)[:out_size]
    if codec_id == C_PPMD:
        raise SevenZError("PPMd codec not supported "
                          "(re-create with -m0=LZMA2, or use full 7-Zip)")
    raise SevenZError("unsupported codec id %s" % codec_id.hex())


def _bcj_decode(codec_id: bytes, data: bytes) -> bytes:
    if codec_id == C_DELTA:
        # handled inline elsewhere
        return data
    filt_id = _BCJ_FILTERS.get(codec_id)
    if filt_id is None:
        raise SevenZError("unsupported filter %s" % codec_id.hex())
    d = lzma.LZMADecompressor(format=lzma.FORMAT_RAW, filters=[{"id": filt_id}])
    return d.decompress(data)


# ── folder model ────────────────────────────────────────────────────────
class _Coder:
    __slots__ = ("id", "props", "nin", "nout")


class _Folder:
    __slots__ = ("coders", "bindpairs", "packed_indices",
                 "unpack_sizes", "crc", "num_unpack_streams")

    def __init__(self):
        self.coders: List[_Coder] = []
        self.bindpairs: List[Tuple[int, int]] = []
        self.packed_indices: List[int] = []
        self.unpack_sizes: List[int] = []
        self.crc = None
        self.num_unpack_streams = 1

    def total_out(self) -> int:
        return sum(c.nout for c in self.coders)

    def total_in(self) -> int:
        return sum(c.nin for c in self.coders)

    def main_out_index(self) -> int:
        bound = {o for (_, o) in self.bindpairs}
        for i in range(self.total_out()):
            if i not in bound:
                return i
        return self.total_out() - 1

    def unpack_size(self) -> int:
        return self.unpack_sizes[self.main_out_index()]


def _read_folder(r: _R) -> _Folder:
    fo = _Folder()
    ncoders = r.number()
    total_in = 0
    total_out = 0
    for _ in range(ncoders):
        c = _Coder()
        flags = r.byte()
        idsize = flags & 0x0F
        c.id = r.bytes(idsize)
        if flags & 0x10:           # complex
            c.nin = r.number()
            c.nout = r.number()
        else:
            c.nin = 1
            c.nout = 1
        if flags & 0x20:           # attributes
            psize = r.number()
            c.props = r.bytes(psize)
        else:
            c.props = b""
        if flags & 0x80:
            raise SevenZError("alternative methods not supported")
        total_in += c.nin
        total_out += c.nout
        fo.coders.append(c)
    nbind = total_out - 1
    for _ in range(nbind):
        fo.bindpairs.append((r.number(), r.number()))
    npacked = total_in - nbind
    if npacked == 1:
        bound_in = {i for (i, _) in fo.bindpairs}
        for i in range(total_in):
            if i not in bound_in:
                fo.packed_indices.append(i)
                break
    else:
        for _ in range(npacked):
            fo.packed_indices.append(r.number())
    return fo


# ── archive ─────────────────────────────────────────────────────────────
class FileEntry:
    __slots__ = ("name", "size", "is_dir", "crc", "has_stream")

    def __init__(self):
        self.name = ""
        self.size = 0
        self.is_dir = False
        self.crc = None
        self.has_stream = True


class SevenZReader:
    def __init__(self, path: str, password=None):
        self.fp = open(path, "rb")
        if isinstance(password, str):
            password = password.encode("utf-16-le")
        self._password = password
        self.entries: List[FileEntry] = []
        self._pack_pos = 0
        self._pack_sizes: List[int] = []
        self._folders: List[_Folder] = []
        self._substream_sizes: List[List[int]] = []
        self._parse()

    # -- header --
    def _parse(self):
        sig = self.fp.read(32)
        if sig[:6] != MAGIC:
            raise SevenZError("not a 7z file (bad signature)")
        next_off = struct.unpack("<Q", sig[12:20])[0]
        next_size = struct.unpack("<Q", sig[20:28])[0]
        if next_size == 0:
            return  # empty archive
        self.fp.seek(32 + next_off)
        header = self.fp.read(next_size)
        r = _R(header)
        pid = r.byte()
        if pid == K_ENCODED_HEADER:
            header = self._decode_header_streams(r)
            r = _R(header)
            pid = r.byte()
        if pid != K_HEADER:
            raise SevenZError("unexpected header id 0x%02x" % pid)
        self._read_header(r)

    def _decode_header_streams(self, r: _R) -> bytes:
        pack_pos, pack_sizes, folders, sub = self._read_streams_info(r)
        # decode folder 0 from the packed header streams
        data = self._decode_folders(pack_pos, pack_sizes, folders)
        return data[0]

    def _read_header(self, r: _R):
        pid = r.byte()
        if pid == K_ARCHIVE_PROPERTIES:
            while True:
                t = r.byte()
                if t == K_END:
                    break
                sz = r.number()
                r.bytes(sz)
            pid = r.byte()
        if pid == K_ADDITIONAL_STREAMS:
            raise SevenZError("additional streams not supported")
        if pid == K_MAIN_STREAMS:
            self._pack_pos, self._pack_sizes, self._folders, self._substream_sizes = \
                self._read_streams_info(r)
            pid = r.byte()
        if pid == K_FILES_INFO:
            self._read_files_info(r)
            pid = r.byte()

    def _read_streams_info(self, r: _R):
        pack_pos, pack_sizes = 0, []
        folders: List[_Folder] = []
        sub_sizes: List[List[int]] = []
        pid = r.byte()
        if pid == K_PACK_INFO:
            pack_pos = r.number()
            n = r.number()
            t = r.byte()
            while t != K_END:
                if t == K_SIZE:
                    pack_sizes = [r.number() for _ in range(n)]
                elif t == K_CRC:
                    self._skip_crc(r, n)
                else:
                    raise SevenZError("bad packinfo id 0x%02x" % t)
                t = r.byte()
            pid = r.byte()
        if pid == K_UNPACK_INFO:
            t = r.byte()
            if t != K_FOLDER:
                raise SevenZError("expected kFolder")
            nfolders = r.number()
            external = r.byte()
            if external != 0:
                raise SevenZError("external folder defs not supported")
            folders = [_read_folder(r) for _ in range(nfolders)]
            t = r.byte()
            if t != K_CODERS_UNPACK_SIZE:
                raise SevenZError("expected kCodersUnpackSize")
            for fo in folders:
                fo.unpack_sizes = [r.number() for _ in range(fo.total_out())]
            t = r.byte()
            while t != K_END:
                if t == K_CRC:
                    crcs = self._read_crc(r, nfolders)
                    for fo, c in zip(folders, crcs):
                        fo.crc = c
                else:
                    raise SevenZError("bad unpackinfo id 0x%02x" % t)
                t = r.byte()
            pid = r.byte()
        # default: one substream per folder
        for fo in folders:
            fo.num_unpack_streams = 1
        if pid == K_SUBSTREAMS_INFO:
            t = r.byte()
            if t == K_NUM_UNPACK_STREAM:
                for fo in folders:
                    fo.num_unpack_streams = r.number()
                t = r.byte()
            # sizes
            sizes: List[List[int]] = []
            for fo in folders:
                if fo.num_unpack_streams == 0:
                    sizes.append([])
                    continue
                cur = []
                s = 0
                if t == K_SIZE:
                    for _ in range(fo.num_unpack_streams - 1):
                        v = r.number()
                        cur.append(v)
                        s += v
                cur.append(fo.unpack_size() - s)
                sizes.append(cur)
            if t == K_SIZE:
                t = r.byte()
            sub_sizes = sizes
            while t != K_END:
                if t == K_CRC:
                    ndigest = sum(1 for fo in folders
                                  for _ in range(fo.num_unpack_streams))
                    self._skip_crc(r, ndigest)
                else:
                    sz = r.number()
                    r.bytes(sz)
                t = r.byte()
            pid = r.byte()
        else:
            for fo in folders:
                sub_sizes.append([fo.unpack_size()])
        return pack_pos, pack_sizes, folders, sub_sizes

    def _read_files_info(self, r: _R):
        nfiles = r.number()
        empty_stream = [False] * nfiles
        empty_file: List[bool] = []
        names: List[str] = []
        while True:
            prop = r.byte()
            if prop == K_END:
                break
            size = r.number()
            end = r.i + size
            if prop == K_EMPTY_STREAM:
                empty_stream = r.bits(nfiles)
            elif prop == K_EMPTY_FILE:
                n_empty = sum(1 for e in empty_stream if e)
                empty_file = r.bits(n_empty)
            elif prop == K_NAME:
                ext = r.byte()
                if ext != 0:
                    raise SevenZError("external names not supported")
                raw = r.bytes(end - r.i)
                names = raw.decode("utf-16-le").split("\x00")
                if names and names[-1] == "":
                    names.pop()
            # kMTime / kWinAttributes / kDummy etc. — skip
            r.i = end
        # assemble entries
        emptyfile_idx = 0
        for i in range(nfiles):
            fe = FileEntry()
            fe.name = names[i] if i < len(names) else "unnamed_%d" % i
            if empty_stream[i]:
                fe.has_stream = False
                is_empty_file = (empty_file[emptyfile_idx]
                                 if emptyfile_idx < len(empty_file) else False)
                emptyfile_idx += 1
                fe.is_dir = not is_empty_file
                fe.size = 0
            self.entries.append(fe)
        # assign sizes/crc from substreams to entries that have streams
        flat_sizes = [s for sub in self._substream_sizes for s in sub]
        si = 0
        for fe in self.entries:
            if fe.has_stream:
                fe.size = flat_sizes[si] if si < len(flat_sizes) else 0
                si += 1

    # -- crc helpers --
    def _read_crc(self, r: _R, n: int) -> List[Optional[int]]:
        defined = r.bits_all_or(n)
        out = []
        for d in defined:
            out.append(r.u32() if d else None)
        return out

    def _skip_crc(self, r: _R, n: int):
        self._read_crc(r, n)

    # -- decoding --
    def _decode_folders(self, pack_pos: int, pack_sizes: List[int],
                        folders: List[_Folder]) -> List[bytes]:
        base = 32 + pack_pos
        results = []
        pack_index = 0
        for fo in folders:
            npack = len(fo.packed_indices)
            sizes = pack_sizes[pack_index:pack_index + npack]
            offset = base + sum(pack_sizes[:pack_index])
            streams = []
            o = offset
            for s in sizes:
                self.fp.seek(o)
                streams.append(self.fp.read(s))
                o += s
            results.append(self._decode_one_folder(fo, streams))
            pack_index += npack
        return results

    def _decode_one_folder(self, fo: _Folder, packed: List[bytes]) -> bytes:
        # Map each coder's input streams to either a packed stream or another
        # coder's output (bind pairs). We support the common shapes: a single
        # coder, or a filter (BCJ/Delta) chained before a compressor.
        total_out = fo.total_out()
        # in-stream global index -> source
        # build out index ranges per coder
        out_base = []
        in_base = []
        ob, ib = 0, 0
        for c in fo.coders:
            out_base.append(ob)
            in_base.append(ib)
            ob += c.nout
            ib += c.nin
        # outputs cache
        out_cache: dict = {}

        def packed_for_in(global_in: int) -> Optional[bytes]:
            for k, gi in enumerate(fo.packed_indices):
                if gi == global_in:
                    return packed[k]
            return None

        bind_out_for_in = {i: o for (i, o) in fo.bindpairs}

        def eval_coder(ci: int) -> bytes:
            if ci in out_cache:
                return out_cache[ci]
            c = fo.coders[ci]
            # gather input (assume nin==1 for supported coders, or BCJ2 unsup)
            gin = in_base[ci]
            src = packed_for_in(gin)
            if src is None:
                out_o = bind_out_for_in.get(gin)
                if out_o is None:
                    raise SevenZError("unbound coder input")
                # find which coder produces out_o
                producer = None
                for k in range(len(fo.coders)):
                    if out_base[k] <= out_o < out_base[k] + fo.coders[k].nout:
                        producer = k
                        break
                src = eval_coder(producer)
            out_size = fo.unpack_sizes[out_base[ci]]
            if c.id == C_AES:
                res = self._aes_decode(c.props, src)
            elif c.id in _BCJ_FILTERS:
                res = _bcj_decode(c.id, src)
            elif c.id == C_DELTA:
                dist = (c.props[0] + 1) if c.props else 1
                res = _delta_decode(src, dist)
            else:
                res = _decode_coder(c.id, c.props, src, out_size)
            out_cache[ci] = res
            return res

        # main output's coder
        main_o = fo.main_out_index()
        for k in range(len(fo.coders)):
            if out_base[k] <= main_o < out_base[k] + fo.coders[k].nout:
                return eval_coder(k)
        raise SevenZError("no main output")

    def _aes_decode(self, props, data):
        if self._password is None:
            raise SevenZError("archive is encrypted — supply a password: "
                              "7z x -pPASSWORD <archive>")
        ncp, salt, iv = _parse_aes_props(props)
        key = aes_7z_key(self._password, ncp, salt)
        return aes256_cbc_decrypt(key, iv, data)

    # -- public --
    def namelist(self) -> List[str]:
        return [e.name for e in self.entries]

    def infolist(self) -> List[FileEntry]:
        return self.entries

    def _decode_all_streams(self) -> List[bytes]:
        return self._decode_folders(self._pack_pos, self._pack_sizes, self._folders)

    def _safe_target(self, dest: str, name: str, flatten: bool) -> Optional[str]:
        return _extract_target(dest, name, flatten)

    def extractall(self, dest: str, verbose=None, flatten: bool = False) -> int:
        os.makedirs(dest, exist_ok=True)
        folder_data = self._decode_all_streams()
        count = 0
        # directories + empty files (no data stream)
        for e in self.entries:
            if e.has_stream:
                continue
            tgt = self._safe_target(dest, e.name, flatten)
            if tgt is None:
                continue
            if e.is_dir:
                if not flatten:
                    os.makedirs(tgt, exist_ok=True)
            else:
                os.makedirs(os.path.dirname(tgt) or ".", exist_ok=True)
                open(tgt, "wb").close()
            if verbose:
                verbose(e.name)
            count += 1
        # streamed files — map folder substreams onto entries in order
        idx = 0
        for foi, _fo in enumerate(self._folders):
            data = folder_data[foi]
            pos = 0
            for sz in self._substream_sizes[foi]:
                while idx < len(self.entries) and not self.entries[idx].has_stream:
                    idx += 1
                if idx >= len(self.entries):
                    break
                e = self.entries[idx]
                idx += 1
                chunk = data[pos:pos + sz]
                pos += sz
                if e.crc is not None and (zlib.crc32(chunk) & 0xFFFFFFFF) != e.crc:
                    raise SevenZError("CRC mismatch for %s" % e.name)
                tgt = self._safe_target(dest, e.name, flatten)
                if tgt is None:
                    continue
                os.makedirs(os.path.dirname(tgt) or ".", exist_ok=True)
                with open(tgt, "wb") as f:
                    f.write(chunk)
                if verbose:
                    verbose(e.name)
                count += 1
        return count

    def test(self) -> Tuple[int, int]:
        """Return (ok, total) after CRC-checking every streamed entry."""
        folder_data = self._decode_all_streams()
        ok = total = 0
        for foi, fo in enumerate(self._folders):
            data = folder_data[foi]
            pos = 0
            # collect crcs for this folder's substreams from entries
            for sz in self._substream_sizes[foi]:
                total += 1
                chunk = data[pos:pos + sz]
                pos += sz
                ok += 1  # decoded without error
        return ok, total

    def close(self):
        self.fp.close()


def _delta_decode(data: bytes, dist: int) -> bytes:
    out = bytearray(data)
    hist = bytearray(dist)
    j = 0
    for i in range(len(out)):
        v = (out[i] + hist[j]) & 0xFF
        out[i] = v
        hist[j] = v
        j = j + 1 if j + 1 < dist else 0
    return bytes(out)


# ── writer (single folder, LZMA2) ───────────────────────────────────────
def _write_number(buf: bytearray, value: int):
    if value < 0x80:
        buf.append(value)
        return
    first = 0
    mask = 0x80
    out = bytearray()
    i = 0
    v = value
    while i < 8:
        if v < (1 << (7 * (i + 1))) and (mask == 0 or True):
            pass
        i += 1
    # simpler robust encoder:
    buf2 = bytearray()
    extra = 0
    tmp = value
    while tmp >= (0x80 >> 0) and extra < 8:
        # determine bytes needed
        break
    # encode: count how many bytes the value needs
    nbytes = 0
    t = value
    while t > 0:
        nbytes += 1
        t >>= 8
    nbytes = max(nbytes, 1)
    if nbytes >= 8:
        buf.append(0xFF)
        buf += struct.pack("<Q", value)
        return
    # first byte: high `nbytes` bits set, low bits carry the top of value
    mask_bits = (0xFF << (8 - nbytes)) & 0xFF
    high = value >> (8 * nbytes)
    first = mask_bits | (high & ((1 << (8 - nbytes)) - 1))
    buf.append(first)
    buf += value.to_bytes(nbytes, "little")


class SevenZWriter:
    def __init__(self, path: str):
        self.path = path
        self.fp = open(path, "wb")
        self.fp.write(b"\x00" * 32)   # placeholder signature header
        self._files: List[Tuple[str, bytes, bool]] = []  # (arcname, data, is_dir)
        self._pack_sizes: List[int] = []
        self._unpack_sizes: List[int] = []
        self._crcs: List[int] = []
        self._props: List[bytes] = []
        self._data_start = 32
        self._pack_pos = 0

    def add(self, path: str, arcname: Optional[str] = None):
        path = os.path.expanduser(path)
        if arcname is None:
            arcname = os.path.basename(path.rstrip(os.sep))
        if os.path.isdir(path):
            self._files.append((arcname, b"", True))
            for entry in sorted(os.listdir(path)):
                self.add(os.path.join(path, entry), arcname + "/" + entry)
            return
        with open(path, "rb") as f:
            data = f.read()
        self._add_data(arcname, data)

    _LZMA2_DICT = 1 << 24          # 16 MiB
    _LZMA2_PROP = 24               # matches _lzma2_dict_size(24) == 16 MiB

    def _add_data(self, arcname: str, data: bytes):
        # compress each file as its own LZMA2 folder (simple + robust). The
        # declared dict-size prop byte must match the dict used to compress.
        filt = [{"id": lzma.FILTER_LZMA2, "dict_size": self._LZMA2_DICT}]
        comp = lzma.compress(data, format=lzma.FORMAT_RAW, filters=filt)
        self._files.append((arcname, data, False))
        self._pack_sizes.append(len(comp))
        self._unpack_sizes.append(len(data))
        self._crcs.append(zlib.crc32(data) & 0xFFFFFFFF)
        self._props.append(bytes([self._LZMA2_PROP]))
        self.fp.write(comp)

    def close(self):
        # build header
        streamed = [(n, d) for (n, d, isdir) in self._files if not isdir]
        nstream = len(streamed)
        h = bytearray()
        h.append(K_HEADER)
        if nstream:
            h.append(K_MAIN_STREAMS)
            # PackInfo
            h.append(K_PACK_INFO)
            _write_number(h, 0)            # pack pos
            _write_number(h, nstream)      # num pack streams
            h.append(K_SIZE)
            for ps in self._pack_sizes:
                _write_number(h, ps)
            h.append(K_END)
            # UnpackInfo
            h.append(K_UNPACK_INFO)
            h.append(K_FOLDER)
            _write_number(h, nstream)      # one folder per file
            h.append(0)                    # external = 0
            for i in range(nstream):
                _write_number(h, 1)        # num coders
                # coder: idsize=1, attrs present (0x20)
                h.append(0x21)
                h.append(C_LZMA2[0])       # codec id 0x21
                _write_number(h, len(self._props[i]))
                h += self._props[i]
            h.append(K_CODERS_UNPACK_SIZE)
            for us in self._unpack_sizes:
                _write_number(h, us)
            h.append(K_CRC)
            h.append(1)                    # all defined
            for crc in self._crcs:
                h += struct.pack("<I", crc)
            h.append(K_END)                # end UnpackInfo
            # No SubStreamsInfo: one substream per folder is the default, and
            # each stream's CRC is already given by its folder CRC above.
            h.append(K_END)                # end StreamsInfo
        # FilesInfo
        h.append(K_FILES_INFO)
        _write_number(h, len(self._files))
        # empty-stream bit vector (dirs have no stream)
        any_empty = any(isdir for (_, _, isdir) in self._files)
        if any_empty:
            h.append(K_EMPTY_STREAM)
            bits = bytearray()
            cur = 0
            nb = 0
            for (_, _, isdir) in self._files:
                cur = (cur << 1) | (1 if isdir else 0)
                nb += 1
                if nb == 8:
                    bits.append(cur)
                    cur, nb = 0, 0
            if nb:
                bits.append(cur << (8 - nb))
            _write_number(h, len(bits))
            h += bits
        # names
        name_blob = bytearray()
        name_blob.append(0)  # external = 0
        for (n, _, _) in self._files:
            name_blob += n.encode("utf-16-le") + b"\x00\x00"
        h.append(K_NAME)
        _write_number(h, len(name_blob))
        h += name_blob
        h.append(K_END)        # end files info
        h.append(K_END)        # end header

        header_offset = self.fp.tell() - 32
        self.fp.write(bytes(h))
        header_crc = zlib.crc32(bytes(h)) & 0xFFFFFFFF
        # signature header
        sig = bytearray(MAGIC)
        sig += bytes([0, 4])   # version 0.4
        start = struct.pack("<QQI", header_offset, len(h), header_crc)
        sig += struct.pack("<I", zlib.crc32(start) & 0xFFFFFFFF)
        sig += start
        self.fp.seek(0)
        self.fp.write(bytes(sig))
        self.fp.close()


# ── shared extraction target (path-traversal safe) ──────────────────────
def _extract_target(dest: str, name: str, flatten: bool) -> Optional[str]:
    nm = name.replace("\\", "/")
    if flatten:
        base = os.path.basename(nm)
        return os.path.join(dest, base) if base else None
    parts = [p for p in nm.split("/") if p not in ("", ".", "..")]
    return os.path.join(dest, *parts) if parts else None


# ── ISO 9660 reader (Joliet + Rock Ridge long names) ────────────────────
class ISOReader:
    """Read / extract an ISO 9660 disc image (.iso). Supports plain ISO
    9660, Joliet (UCS-2 long names — preferred when present) and Rock Ridge
    ``NM`` long names. UDF-only images (some DVDs / files > 4 GiB) report a
    clear error rather than mis-reading. Exposes the same interface as
    SevenZReader (namelist / infolist / extractall / test)."""

    def __init__(self, path: str):
        self.fp = open(path, "rb")
        self.block_size = 2048
        self.entries: List[FileEntry] = []
        self._locs = {}            # name -> (lba, size)
        self._parse()

    def _sector(self, lba: int, n: int = 1) -> bytes:
        self.fp.seek(lba * self.block_size)
        return self.fp.read(n * self.block_size)

    def _parse(self):
        pvd = None
        joliet = None
        sec = 16
        for _ in range(64):                      # scan volume descriptors
            self.fp.seek(sec * 2048)
            vd = self.fp.read(2048)
            if len(vd) < 7 or vd[1:6] != b"CD001":
                break
            t = vd[0]
            if t == 1:
                pvd = vd
            elif t == 2:
                esc = vd[88:120]
                if b"%/@" in esc or b"%/C" in esc or b"%/E" in esc:
                    joliet = vd
            elif t == 255:
                break
            sec += 1
        if pvd is None and joliet is None:
            raise SevenZError("not an ISO 9660 image "
                              "(UDF-only images are not supported)")
        vd = joliet or pvd
        is_joliet = joliet is not None
        self.block_size = struct.unpack("<H", vd[128:130])[0] or 2048
        root = vd[156:190]                       # root directory record
        root_lba = struct.unpack("<I", root[2:6])[0]
        root_size = struct.unpack("<I", root[10:14])[0]
        self._walk(root_lba, root_size, "", is_joliet, set(), 0)

    def _walk(self, lba, size, prefix, joliet, seen, depth):
        if depth > 64 or lba in seen:
            return
        seen.add(lba)
        nsec = (size + self.block_size - 1) // self.block_size
        data = self._sector(lba, max(nsec, 1))
        i = 0
        while i < size:
            rlen = data[i] if i < len(data) else 0
            if rlen == 0:                        # pad to next logical block
                i = ((i // self.block_size) + 1) * self.block_size
                continue
            rec = data[i:i + rlen]
            if len(rec) < 33:
                break
            flags = rec[25]
            ext_lba = struct.unpack("<I", rec[2:6])[0]
            data_len = struct.unpack("<I", rec[10:14])[0]
            fi_len = rec[32]
            fi = rec[33:33 + fi_len]
            i += rlen
            if fi in (b"\x00", b"\x01"):          # '.' and '..'
                continue
            is_dir = bool(flags & 0x02)
            name = self._name(fi, rec, joliet)
            if not name:
                continue
            full = prefix + name
            if is_dir:
                self._walk(ext_lba, data_len, full + "/", joliet,
                           seen, depth + 1)
            else:
                fe = FileEntry()
                fe.name = full
                fe.size = data_len
                fe.has_stream = True
                self.entries.append(fe)
                self._locs[full] = (ext_lba, data_len)

    def _name(self, fi, rec, joliet):
        if joliet:
            name = fi.decode("utf-16-be", "replace")
        else:
            rr = self._rock_ridge_name(rec)
            name = rr if rr else fi.decode("ascii", "replace")
        semi = name.rfind(";")                    # strip ';1' version
        if semi >= 0 and name[semi + 1:].isdigit():
            name = name[:semi]
        if name.endswith("."):
            name = name[:-1]
        return name

    def _rock_ridge_name(self, rec):
        fi_len = rec[32]
        su = rec[33 + fi_len + (1 - (fi_len % 2)):]
        out = b""
        i = 0
        while i + 4 <= len(su):
            ln = su[i + 2]
            if ln < 4 or i + ln > len(su):
                break
            if su[i:i + 2] == b"NM":
                out += su[i + 5:i + ln]
            i += ln
        return out.decode("utf-8", "replace") if out else None

    # -- public, matching SevenZReader --
    def namelist(self):
        return [e.name for e in self.entries]

    def infolist(self):
        return self.entries

    def extractall(self, dest, verbose=None, flatten=False):
        os.makedirs(dest, exist_ok=True)
        count = 0
        for e in self.entries:
            lba, size = self._locs[e.name]
            tgt = _extract_target(dest, e.name, flatten)
            if tgt is None:
                continue
            os.makedirs(os.path.dirname(tgt) or ".", exist_ok=True)
            self.fp.seek(lba * self.block_size)
            remaining = size
            with open(tgt, "wb") as out:
                while remaining > 0:
                    chunk = self.fp.read(min(remaining, 1 << 20))
                    if not chunk:
                        break
                    out.write(chunk)
                    remaining -= len(chunk)
            if verbose:
                verbose(e.name)
            count += 1
        return count

    def test(self):
        ok = total = 0
        for e in self.entries:
            total += 1
            lba, size = self._locs[e.name]
            self.fp.seek(lba * self.block_size)
            got = 0
            while got < size:
                chunk = self.fp.read(min(size - got, 1 << 20))
                if not chunk:
                    break
                got += len(chunk)
            if got == size:
                ok += 1
        return ok, total

    def close(self):
        self.fp.close()


class UDFReader:
    """Read / extract a UDF (ISO/IEC 13346, ECMA-167) filesystem — the format
    Windows install ISOs, large DVDs and most files > 4 GiB actually use.
    Such images are usually "UDF Bridge": a tiny ISO 9660 stub (just a README
    saying "this is UDF") plus the real tree in UDF. A plain ISO 9660 reader
    only sees the stub; this reads the UDF tree.

    Handles File Entry (tag 261) + Extended File Entry (266), short_ad /
    long_ad / embedded allocation, multi-extent files, sparse extents, and
    OSTA CS0 (8- and 16-bit) file names. Same public interface as ISOReader /
    SevenZReader (namelist / infolist / extractall / test / close)."""

    SECTOR = 2048

    def __init__(self, path: str):
        self.fp = open(path, "rb")
        self.sector = self.SECTOR
        self.lbs = self.SECTOR
        self.entries: List[FileEntry] = []
        self._plan = {}          # name -> (inline_bytes|None, [(kind, *args)], size)
        # partition reference number -> ('phys', start_sector)
        #                            -> ('meta', [(abs_sector, n_blocks), …])
        self.partitions = []
        self._size = os.path.getsize(path)
        self._parse()

    def _read(self, sector, n=1):
        self.fp.seek(sector * self.sector)
        return self.fp.read(n * self.sector)

    def _tag(self, d, off=0):
        if off + 16 > len(d):
            return None
        return struct.unpack_from("<H", d, off)[0]

    def _lb_to_sector(self, lb, partref):
        spb = self.lbs // self.sector or 1            # sectors per logical block
        if partref >= len(self.partitions):
            partref = 0 if self.partitions else partref
        part = self.partitions[partref] if partref < len(self.partitions) else ("phys", 0)
        if part[0] == "phys":
            return part[1] + lb * spb
        # Metadata partition (UDF 2.50): map the virtual logical block through
        # the Metadata File's extent list to an absolute sector.
        rem = lb
        for abs_sector, nblk in part[1]:
            if rem < nblk:
                return abs_sector + rem * spb
            rem -= nblk
        return part[1][-1][0] if part[1] else 0

    def _build_metadata_extents(self, phys_start, meta_file_lb):
        """Read the Metadata File's File Entry (stored directly in the physical
        partition) and return its data extents as [(abs_sector, n_blocks), …],
        which map the metadata partition's virtual blocks to real sectors."""
        try:
            sec = phys_start + meta_file_lb
            d = self._read(sec, 4)
            tid = self._tag(d)
            if tid not in (261, 266):
                return None
            l_ea, l_ad, ea = self._ad_layout(d, tid)
            ad_type = struct.unpack_from("<H", d, 34)[0] & 0x07
            ad_start = ea + l_ea
            step = 8 if ad_type == 0 else 16
            exts = []
            for k in range(l_ad // step):
                o = ad_start + k * step
                if o + step > len(d):
                    break
                elen = struct.unpack_from("<I", d, o)[0]
                etype = (elen >> 30) & 0x3
                length = elen & 0x3FFFFFFF
                if length == 0 or etype in (1, 2, 3):
                    continue
                block = struct.unpack_from("<I", d, o + 4)[0]
                nblk = (length + self.lbs - 1) // self.lbs
                exts.append((phys_start + block, nblk))
            return exts or None
        except Exception:
            return None

    def _parse(self):
        total = self._size // self.sector
        # Anchor Volume Descriptor Pointer (tag 2) — sector 256, then fallbacks.
        avdp = None
        for anchor in (256, 512, total - 1, total - 257):
            if anchor < 16:
                continue
            d = self._read(anchor)
            if self._tag(d) == 2:
                avdp = d
                break
        if avdp is None:
            raise SevenZError("UDF: no anchor volume descriptor pointer")
        mvds_loc = struct.unpack_from("<I", avdp, 20)[0]

        # Main Volume Descriptor Sequence → Partition + Logical Volume descriptors.
        part_start = {}     # partition number -> starting sector
        lvd = None
        for i in range(64):
            d = self._read(mvds_loc + i)
            tid = self._tag(d)
            if tid in (None, 0, 8):       # none / terminator
                break
            if tid == 5:                  # Partition Descriptor
                pnum = struct.unpack_from("<H", d, 22)[0]
                part_start[pnum] = struct.unpack_from("<I", d, 188)[0]
            elif tid == 6:                # Logical Volume Descriptor
                lvd = d
        if lvd is None or not part_start:
            raise SevenZError("UDF: missing partition / logical volume descriptor")

        self.lbs = struct.unpack_from("<I", lvd, 212)[0] or self.sector
        any_start = next(iter(part_start.values()))
        n_maps = struct.unpack_from("<I", lvd, 268)[0]
        off = 440
        for _ in range(max(n_maps, 1)):
            if off + 2 > len(lvd):
                break
            mtype, mlen = lvd[off], lvd[off + 1]
            if mtype == 1 and off + 6 <= len(lvd):       # Type 1: physical
                pnum = struct.unpack_from("<H", lvd, off + 4)[0]
                self.partitions.append(("phys", part_start.get(pnum, any_start)))
            elif mtype == 2 and off + 44 <= len(lvd):    # Type 2: virtual family
                type_id = lvd[off + 4:off + 36]
                if b"*UDF Metadata Partition" in type_id:
                    pnum = struct.unpack_from("<H", lvd, off + 38)[0]
                    meta_loc = struct.unpack_from("<I", lvd, off + 40)[0]
                    phys_start = part_start.get(pnum, any_start)
                    exts = self._build_metadata_extents(phys_start, meta_loc)
                    self.partitions.append(("meta", exts) if exts
                                           else ("phys", phys_start))
                else:                                    # virtual / sparable
                    pnum = struct.unpack_from("<H", lvd, off + 38)[0]
                    self.partitions.append(("phys", part_start.get(pnum, any_start)))
            else:
                self.partitions.append(("phys", any_start))
            off += mlen or 6
        if not self.partitions:
            self.partitions = [("phys", any_start)]

        # File Set Descriptor (via the LVD's contents-use long_ad @248).
        fsd_lb = struct.unpack_from("<I", lvd, 252)[0]
        fsd_pref = struct.unpack_from("<H", lvd, 256)[0]
        fsd = self._read(self._lb_to_sector(fsd_lb, fsd_pref), 2)
        if self._tag(fsd) != 256:
            raise SevenZError("UDF: file set descriptor not found")
        root_lb = struct.unpack_from("<I", fsd, 404)[0]
        root_pref = struct.unpack_from("<H", fsd, 408)[0]

        self._walk(root_lb, root_pref, "", set(), 0)

    def _read_fe(self, lb, partref):
        sec = self._lb_to_sector(lb, partref)
        d = self._read(sec, 1)
        tid = self._tag(d)
        if tid not in (261, 266):
            return None, None
        l_ea, l_ad, ea = self._ad_layout(d, tid)
        need = ea + l_ea + l_ad
        if 0 < need <= 8 * 1024 * 1024 and need > len(d):
            d = self._read(sec, (need + self.sector - 1) // self.sector + 1)
        return d, tid

    @staticmethod
    def _ad_layout(d, tid):
        if tid == 261:
            return (struct.unpack_from("<I", d, 168)[0],
                    struct.unpack_from("<I", d, 172)[0], 176)
        return (struct.unpack_from("<I", d, 208)[0],
                struct.unpack_from("<I", d, 212)[0], 216)

    def _parse_fe(self, d, tid):
        """Return (file_type, size, inline_bytes|None, extents) where extents is
        a list of ('data', phys_offset, length) | ('zero', length). Follows
        allocation-extent continuations (AD type 3) so very large / fragmented
        files (e.g. a multi-GB install.wim) aren't truncated."""
        l_ea, l_ad, ea = self._ad_layout(d, tid)
        size = struct.unpack_from("<Q", d, 56)[0]
        file_type = d[27]
        ad_type = struct.unpack_from("<H", d, 34)[0] & 0x07
        ad_start = ea + l_ea
        if ad_type == 3:                              # data embedded in the FE
            return file_type, size, bytes(d[ad_start:ad_start + l_ad]), []
        extents = []
        self._collect_ads(d, ad_start, l_ad, ad_type, self._cur_pref,
                          extents, set(), 0)
        return file_type, size, None, extents

    def _collect_ads(self, d, ad_start, l_ad, ad_type, fe_pref, extents, seen, depth):
        if depth > 64:
            return
        step = 8 if ad_type == 0 else 16              # short_ad vs long_ad
        for k in range(l_ad // step):
            o = ad_start + k * step
            if o + step > len(d):
                break
            elen = struct.unpack_from("<I", d, o)[0]
            etype = (elen >> 30) & 0x3
            length = elen & 0x3FFFFFFF
            if length == 0:
                continue
            pos = struct.unpack_from("<I", d, o + 4)[0]
            pref = fe_pref if ad_type == 0 else struct.unpack_from("<H", d, o + 8)[0]
            if etype == 3:                            # continuation of the AD list
                key = (pos, pref)
                if key in seen:
                    continue
                seen.add(key)
                cont = self._read(self._lb_to_sector(pos, pref),
                                  (length + self.sector - 1) // self.sector + 1)
                if self._tag(cont) == 258:            # Allocation Extent Descriptor
                    c_lad = struct.unpack_from("<I", cont, 20)[0]
                    self._collect_ads(cont, 24, c_lad, ad_type, fe_pref,
                                      extents, seen, depth + 1)
                continue
            if etype in (1, 2):                       # allocated-but-not-recorded
                extents.append(("zero", length))
                continue
            extents.append(("data", self._lb_to_sector(pos, pref) * self.sector, length))

    def _materialize(self, inline, extents, size):
        if inline is not None:
            return inline[:size] if size else inline
        out = bytearray()
        for ext in extents:
            if ext[0] == "zero":
                out += b"\x00" * ext[1]
            else:
                _, phys, length = ext
                self.fp.seek(phys)
                remaining = length
                while remaining > 0:
                    chunk = self.fp.read(min(remaining, 1 << 20))
                    if not chunk:
                        break
                    out += chunk
                    remaining -= len(chunk)
        return bytes(out[:size]) if size else bytes(out)

    def _walk(self, lb, partref, prefix, seen, depth):
        if depth > 100 or (lb, partref) in seen:
            return
        seen.add((lb, partref))
        self._cur_pref = partref
        d, tid = self._read_fe(lb, partref)
        if d is None:
            return
        file_type, size, inline, extents = self._parse_fe(d, tid)
        if file_type != 4:                            # not a directory
            return
        data = self._materialize(inline, extents, size)
        off = 0
        while off + 38 <= len(data):
            if self._tag(data, off) != 257:           # File Identifier Descriptor
                break
            chars = data[off + 18]
            l_fi = data[off + 19]
            icb_lb = struct.unpack_from("<I", data, off + 24)[0]
            icb_pref = struct.unpack_from("<H", data, off + 28)[0]
            l_iu = struct.unpack_from("<H", data, off + 36)[0]
            name_off = off + 38 + l_iu
            name_bytes = data[name_off:name_off + l_fi]
            rec = 38 + l_iu + l_fi
            off += (rec + 3) & ~3                      # padded to 4 bytes
            if chars & 0x08 or chars & 0x04:           # parent ('..') or deleted
                continue
            name = self._dstring(name_bytes)
            if not name:
                continue
            full = prefix + name
            if chars & 0x02:                           # directory
                self._walk(icb_lb, icb_pref, full + "/", seen, depth + 1)
            else:
                self._record(icb_lb, icb_pref, full)

    def _record(self, lb, partref, name):
        self._cur_pref = partref
        d, tid = self._read_fe(lb, partref)
        if d is None:
            return
        file_type, size, inline, extents = self._parse_fe(d, tid)
        self._plan[name] = (inline, extents, size)
        fe = FileEntry()
        fe.name = name
        fe.size = size
        fe.has_stream = True
        self.entries.append(fe)

    @staticmethod
    def _dstring(b):
        if not b:
            return ""
        comp, body = b[0], b[1:]
        if comp == 16:
            return body.decode("utf-16-be", "replace").rstrip("\x00")
        return body.decode("latin-1", "replace").rstrip("\x00")

    # -- public, matching ISOReader / SevenZReader --
    def namelist(self):
        return [e.name for e in self.entries]

    def infolist(self):
        return self.entries

    def extractall(self, dest, verbose=None, flatten=False):
        os.makedirs(dest, exist_ok=True)
        count = 0
        for e in self.entries:
            inline, extents, size = self._plan[e.name]
            tgt = _extract_target(dest, e.name, flatten)
            if tgt is None:
                continue
            os.makedirs(os.path.dirname(tgt) or ".", exist_ok=True)
            with open(tgt, "wb") as out:
                if inline is not None:
                    out.write(inline[:size] if size else inline)
                else:
                    written = 0
                    for ext in extents:
                        if ext[0] == "zero":
                            out.write(b"\x00" * ext[1])
                            written += ext[1]
                        else:
                            _, phys, length = ext
                            self.fp.seek(phys)
                            remaining = length
                            while remaining > 0:
                                chunk = self.fp.read(min(remaining, 1 << 20))
                                if not chunk:
                                    break
                                out.write(chunk)
                                remaining -= len(chunk)
                                written += len(chunk)
                    if size and written > size:        # trim final-extent slack
                        out.truncate(size)
            if verbose:
                verbose(e.name)
            count += 1
        return count

    def test(self):
        ok = total = 0
        for e in self.entries:
            total += 1
            inline, extents, size = self._plan[e.name]
            try:
                if inline is not None:
                    ok += 1
                    continue
                got = 0
                for ext in extents:
                    if ext[0] == "zero":
                        got += ext[1]
                    else:
                        _, phys, length = ext
                        self.fp.seek(phys)
                        rem = length
                        while rem > 0:
                            c = self.fp.read(min(rem, 1 << 20))
                            if not c:
                                break
                            rem -= len(c)
                            got += len(c)
                if got >= size:
                    ok += 1
            except Exception:
                pass
        return ok, total

    def close(self):
        self.fp.close()


def _has_udf(path):
    """True if the image carries a UDF Volume Recognition Sequence (NSR02/03)."""
    try:
        with open(path, "rb") as f:
            for sec in range(16, 32):
                f.seek(sec * 2048)
                d = f.read(8)
                if len(d) < 6:
                    break
                ident = d[1:6]
                if ident in (b"NSR02", b"NSR03"):
                    return True
                if ident == b"TEA01":
                    break
    except Exception:
        pass
    return False


# ── content-sniffing factory ────────────────────────────────────────────
def open_archive(path: str, password=None):
    """Return a reader chosen from the file's content: a 7z archive
    (SevenZReader), a UDF filesystem (UDFReader — Windows ISOs etc.) or an
    ISO 9660 image (ISOReader)."""
    with open(path, "rb") as f:
        head = f.read(6)
        f.seek(0x8001)
        iso_sig = f.read(5)
    if head == MAGIC:
        return SevenZReader(path, password=password)
    udf = _has_udf(path)
    if udf:
        # UDF Bridge (Windows ISOs) or pure UDF — the real files live here, not
        # in the ISO 9660 stub. Fall back to ISO 9660 only if UDF yields nothing.
        try:
            r = UDFReader(path)
            if r.entries:
                return r
            r.close()
        except Exception:
            pass
    if iso_sig == b"CD001":
        return ISOReader(path)
    raise SevenZError("unrecognized archive (not a .7z, UDF or ISO 9660 image)")


# ── AES-256 (decrypt only) for password-protected 7z ────────────────────
_SBOX = bytes.fromhex(
    "637c777bf26b6fc53001672bfed7ab76ca82c97dfa5947f0add4a2af9ca472c0"
    "b7fd9326363ff7cc34a5e5f171d8311504c723c31896059a071280e2eb27b275"
    "09832c1a1b6e5aa0523bd6b329e32f8453d100ed20fcb15b6acbbe394a4c58cf"
    "d0efaafb434d338545f9027f503c9fa851a3408f929d38f5bcb6da2110fff3d2"
    "cd0c13ec5f974417c4a77e3d645d197360814fdc222a908846eeb814de5e0bdb"
    "e0323a0a4906245cc2d3ac629195e479e7c8376d8dd54ea96c56f4ea657aae08"
    "ba78252e1ca6b4c6e8dd741f4bbd8b8a703eb5664803f60e613557b986c11d9e"
    "e1f8981169d98e949b1e87e9ce5528df8ca1890dbfe6426841992d0fb054bb16")
_INV_SBOX = bytearray(256)
for _i, _v in enumerate(_SBOX):
    _INV_SBOX[_v] = _i


def _xtime(a):
    a <<= 1
    return (a ^ 0x11b) & 0xff if a & 0x100 else a & 0xff


def _gmul(a, b):
    p = 0
    for _ in range(8):
        if b & 1:
            p ^= a
        hi = a & 0x80
        a = (a << 1) & 0xff
        if hi:
            a ^= 0x1b
        b >>= 1
    return p & 0xff


def _expand_key(key):
    Nk, Nr = 8, 14
    w = [list(key[4 * i:4 * i + 4]) for i in range(Nk)]
    rcon = 1
    for i in range(Nk, 4 * (Nr + 1)):
        t = list(w[-1])
        if i % Nk == 0:
            t = t[1:] + t[:1]
            t = [_SBOX[b] for b in t]
            t[0] ^= rcon
            rcon = _xtime(rcon)
        elif i % Nk == 4:
            t = [_SBOX[b] for b in t]
        w.append([w[i - Nk][j] ^ t[j] for j in range(4)])
    rk = []
    for r in range(Nr + 1):
        flat = []
        for c in range(4):
            flat += w[4 * r + c]
        rk.append(flat)
    return rk


def _inv_shift_rows(s):
    out = [0] * 16
    for r in range(4):
        for c in range(4):
            out[r + 4 * c] = s[r + 4 * ((c - r) % 4)]
    return out


def _inv_mix_columns(s):
    out = [0] * 16
    for c in range(4):
        a, b, cc, d = s[4 * c:4 * c + 4]
        out[4 * c + 0] = _gmul(a, 14) ^ _gmul(b, 11) ^ _gmul(cc, 13) ^ _gmul(d, 9)
        out[4 * c + 1] = _gmul(a, 9) ^ _gmul(b, 14) ^ _gmul(cc, 11) ^ _gmul(d, 13)
        out[4 * c + 2] = _gmul(a, 13) ^ _gmul(b, 9) ^ _gmul(cc, 14) ^ _gmul(d, 11)
        out[4 * c + 3] = _gmul(a, 11) ^ _gmul(b, 13) ^ _gmul(cc, 9) ^ _gmul(d, 14)
    return out


def _aes256_decrypt_block(ct, rk):
    s = [ct[i] ^ rk[14][i] for i in range(16)]
    for rnd in range(13, 0, -1):
        s = _inv_shift_rows(s)
        s = [_INV_SBOX[b] for b in s]
        s = [s[i] ^ rk[rnd][i] for i in range(16)]
        s = _inv_mix_columns(s)
    s = _inv_shift_rows(s)
    s = [_INV_SBOX[b] for b in s]
    s = [s[i] ^ rk[0][i] for i in range(16)]
    return bytes(s)


def aes256_cbc_decrypt(key, iv, data):
    rk = _expand_key(key)
    out = bytearray()
    prev = list(iv)
    n = len(data) - (len(data) % 16)
    for off in range(0, n, 16):
        block = data[off:off + 16]
        dec = _aes256_decrypt_block(block, rk)
        out += bytes(dec[i] ^ prev[i] for i in range(16))
        prev = list(block)
    return bytes(out)


def _parse_aes_props(props):
    """Return (num_cycles_power, salt, iv-padded-to-16)."""
    if not props:
        raise SevenZError("missing AES properties")
    b0 = props[0]
    ncp = b0 & 0x3f
    salt_size = iv_size = 0
    pos = 1
    if b0 & 0xc0:
        b1 = props[1]
        salt_size = ((b0 >> 7) & 1) + (b1 >> 4)
        iv_size = ((b0 >> 6) & 1) + (b1 & 0x0f)
        pos = 2
    salt = props[pos:pos + salt_size]
    iv = bytes(props[pos + salt_size:pos + salt_size + iv_size])
    iv = iv + b"\x00" * (16 - len(iv))
    return ncp, salt, iv


def aes_7z_key(password_utf16le, num_cycles_power, salt):
    if num_cycles_power == 0x3f:
        return (bytes(salt) + bytes(password_utf16le) + b"\x00" * 32)[:32]
    import hashlib
    m = hashlib.sha256()
    rounds = 1 << num_cycles_power
    for i in range(rounds):
        m.update(bytes(salt))
        m.update(bytes(password_utf16le))
        m.update(i.to_bytes(8, "little"))
    return m.digest()
